import math

class Punto:
    def __init__(self, x: float, y: float) -> None:
        self.x = x
        self.y = y

    def distancia(self, otro: Punto) -> float:     # sin comillas desde 3.14
        return math.hypot(self.x - otro.x, self.y - otro.y)

    def desplazado(self, dx: float, dy: float) -> Punto:
        return Punto(self.x + dx, self.y + dy)     # devuelve un objeto NUEVO

a = Punto(0, 0)
b = a.desplazado(3, 4)
print(a.distancia(b))        # 5.0
print(a.x, a.y, b.x, b.y)    # 0 0 3 4: a no ha cambiado

