class Fecha:
    def __init__(self, dia, mes, anio):
        self.dia = dia
        self.mes = mes
        self.anio = anio

    @classmethod
    def desde_cadena(cls, texto):              # "26/09/2026"
        dia, mes, anio = [int(parte) for parte in texto.split("/")]
        return cls(dia, mes, anio)             # cls, no Fecha: respeta las subclases

    @staticmethod
    def es_bisiesto(anio):
        return anio % 4 == 0 and (anio % 100 != 0 or anio % 400 == 0)

    def a_texto(self):
        return f"{self.dia:02d}/{self.mes:02d}/{self.anio}"

class FechaFiscal(Fecha):                      # herencia: lección 5
    pass

