exercises.solution:
class Reloj:
    MINUTOS_DIA = 24 * 60

    def __init__(self, horas=0, minutos=0):
        self._fijar(horas * 60 + minutos)

    def _fijar(self, total):
        """Guarda un total de minutos normalizado en horas y minutos."""
        total = total % Reloj.MINUTOS_DIA          # con divisor positivo, nunca es negativo
        self.horas, self.minutos = divmod(total, 60)

    def _total(self):
        return self.horas * 60 + self.minutos

    def avanzar(self, minutos):
        self._fijar(self._total() + minutos)
        return self

    def a_texto(self):
        return f"{self.horas:02d}:{self.minutos:02d}"

    def minutos_hasta(self, otro):
        return (otro._total() - self._total()) % Reloj.MINUTOS_DIA

