exercises.solution:
class Color:
    DIGITOS_HEX = "0123456789abcdefABCDEF"

    def __init__(self, r, g, b):
        for valor in (r, g, b):
            if isinstance(valor, bool) or not isinstance(valor, int) or not 0 <= valor <= 255:
                raise ValueError(f"Componente inválida: {valor!r}")
        self.r = r
        self.g = g
        self.b = b

    @staticmethod
    def es_hex_valido(texto):
        if not isinstance(texto, str) or len(texto) != 7 or texto[0] != "#":
            return False
        for caracter in texto[1:]:
            if caracter not in Color.DIGITOS_HEX:
                return False
        return True

    @classmethod
    def desde_hex(cls, texto):
        if not cls.es_hex_valido(texto):
            raise ValueError(f"Color hexadecimal inválido: {texto!r}")
        r = int(texto[1:3], 16)
        g = int(texto[3:5], 16)
        b = int(texto[5:7], 16)
        return cls(r, g, b)          # cls: funciona también con subclases

    def a_hex(self):
        return f"#{self.r:02X}{self.g:02X}{self.b:02X}"

