exercises.solution:
class Temperatura:
    CERO_ABSOLUTO = -273.15

    def __init__(self, celsius=0):
        self.celsius = celsius              # pasa por el setter: valida al crear

    @staticmethod
    def _es_numero(valor):
        return isinstance(valor, (int, float)) and not isinstance(valor, bool)

    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, valor):
        if not self._es_numero(valor):
            raise ValueError(f"La temperatura debe ser un número, no {valor!r}")
        if valor < Temperatura.CERO_ABSOLUTO:
            raise ValueError(f"{valor} °C está por debajo del cero absoluto")
        self._celsius = valor               # nombre distinto: sin recursión

    @property
    def fahrenheit(self):
        return self.celsius * 9 / 5 + 32

    @fahrenheit.setter
    def fahrenheit(self, valor):
        if not self._es_numero(valor):
            raise ValueError(f"La temperatura debe ser un número, no {valor!r}")
        self.celsius = (valor - 32) * 5 / 9   # reutiliza la validación de celsius

    @property
    def kelvin(self):
        return self.celsius - Temperatura.CERO_ABSOLUTO

