class SaldoInsuficienteError(Exception):
    """Se intenta retirar más dinero del disponible."""

    def __init__(self, saldo, cantidad):
        super().__init__(f"Saldo insuficiente: disponible {saldo}, solicitado {cantidad}")
        self.saldo = saldo
        self.cantidad = cantidad


class CuentaBancaria:
    def __init__(self, titular, saldo_inicial=0):
        if not isinstance(titular, str) or not titular.strip():
            raise ValueError("El titular debe ser un texto no vacío")
        if not self._es_numero(saldo_inicial) or saldo_inicial < 0:
            raise ValueError("El saldo inicial debe ser un número mayor o igual que 0")
        self.titular = titular.strip()
        self._saldo = saldo_inicial
        self._movimientos = []                 # una lista NUEVA por cuenta

    @staticmethod
    def _es_numero(valor):
        return isinstance(valor, (int, float)) and not isinstance(valor, bool)

    def _validar_cantidad(self, cantidad):
        if not self._es_numero(cantidad) or cantidad <= 0:
            raise ValueError(f"Cantidad inválida: {cantidad!r}")

    @property
    def saldo(self):
        return self._saldo

    def depositar(self, cantidad):
        self._validar_cantidad(cantidad)
        self._saldo += cantidad
        self._movimientos.append(("deposito", cantidad))
        return self._saldo

    def retirar(self, cantidad):
        self._validar_cantidad(cantidad)
        if cantidad > self._saldo:
            raise SaldoInsuficienteError(self._saldo, cantidad)
        self._saldo -= cantidad
        self._movimientos.append(("retirada", cantidad))
        return self._saldo

    def transferir(self, destino, cantidad):
        if not isinstance(destino, CuentaBancaria):
            raise TypeError("El destino debe ser una CuentaBancaria")
        if destino is self:
            raise ValueError("No se puede transferir a la misma cuenta")
        self.retirar(cantidad)                 # si falla, el destino no se toca
        destino.depositar(cantidad)

    def movimientos(self):
        return list(self._movimientos)         # copia: el historial no se altera desde fuera

