exercises.solution:
class PilaVaciaError(IndexError):
    """Se intentó leer o sacar un elemento de una pila vacía."""


class Pila:
    def __init__(self, elementos=None):
        # list(...) crea una lista nueva: la pila no comparte la del llamador
        self._datos = [] if elementos is None else list(elementos)

    def apilar(self, elemento):
        self._datos.append(elemento)

    def desapilar(self):
        if not self._datos:
            raise PilaVaciaError("desapilar() en una pila vacía")
        return self._datos.pop()

    def cima(self):
        if not self._datos:
            raise PilaVaciaError("cima() en una pila vacía")
        return self._datos[-1]

    def esta_vacia(self):
        return not self._datos

    @property
    def tamanio(self):
        return len(self._datos)

    def __repr__(self):
        return f"{type(self).__name__}({self._datos!r})"

