    def enviar(self, mensaje):
        return f"[consola] {mensaje}"


def difundir(mensaje, canales):
    resultado = {"enviados": [], "rechazados": []}
    for canal in canales:
        enviar = getattr(canal, "enviar", None)    # buscar...
        if enviar is None:
            resultado["rechazados"].append(type(canal).__name__)
        else:
            resultado["enviados"].append(enviar(mensaje))   # ...y llamar, por separado
    return resultado

