exercises.solution:
import math


def _medida(valor):
    """Devuelve valor si es un número positivo; si no, lanza ValueError."""
    if isinstance(valor, bool) or not isinstance(valor, (int, float)) or valor <= 0:
        raise ValueError(f"Las medidas deben ser números positivos: {valor!r}")
    return valor


class Figura:
    """Base de las figuras. Las subclases implementan area, perimetro y escalada."""

    def area(self):
        raise NotImplementedError(f"{type(self).__name__} debe implementar area()")

    def perimetro(self):
        raise NotImplementedError(f"{type(self).__name__} debe implementar perimetro()")

    def escalada(self, factor):
        raise NotImplementedError(f"{type(self).__name__} debe implementar escalada()")

    def describir(self):
        # Método plantilla: el formato es común; los cálculos los pone cada subclase
        return (f"{type(self).__name__}: área={self.area():.2f}, "
                f"perímetro={self.perimetro():.2f}")


class Circulo(Figura):
    def __init__(self, radio):
        self.radio = _medida(radio)

    def area(self):
        return math.pi * self.radio ** 2

    def perimetro(self):
        return 2 * math.pi * self.radio

    def escalada(self, factor):
        return type(self)(self.radio * _medida(factor))


class Rectangulo(Figura):
    def __init__(self, ancho, alto):
        self.ancho = _medida(ancho)
        self.alto = _medida(alto)

    def area(self):
        return self.ancho * self.alto

    def perimetro(self):
        return 2 * (self.ancho + self.alto)

    def escalada(self, factor):
        factor = _medida(factor)
        return type(self)(self.ancho * factor, self.alto * factor)


class Cuadrado(Rectangulo):
    def __init__(self, lado):
        super().__init__(lado, lado)

    @property
    def lado(self):
        return self.ancho

    def escalada(self, factor):
        # La versión heredada llamaría a Cuadrado(ancho, alto): firma distinta
        return type(self)(self.lado * _medida(factor))


def area_total(figuras):
    total = 0
    for figura in figuras:
        total += figura.area()
    return total


def mayor(figuras):
    if not figuras:
        raise ValueError("No hay figuras")
    return max(figuras, key=lambda figura: figura.area())

