exercises.solution:
def _es_numero(valor):
    return isinstance(valor, (int, float)) and not isinstance(valor, bool)


class Empleado:
    def __init__(self, nombre, salario_base):
        if not isinstance(nombre, str) or not nombre.strip():
            raise ValueError("El nombre no puede estar vacío")
        if not _es_numero(salario_base) or salario_base <= 0:
            raise ValueError(f"Salario base inválido: {salario_base!r}")
        self.nombre = nombre
        self.salario_base = salario_base

    def salario(self):
        return self.salario_base


class Gerente(Empleado):
    def __init__(self, nombre, salario_base, bonus_pct):
        super().__init__(nombre, salario_base)          # valida lo común
        if not _es_numero(bonus_pct) or not 0 <= bonus_pct <= 100:
            raise ValueError(f"Bonus inválido: {bonus_pct!r}")
        self.bonus_pct = bonus_pct

    def salario(self):
        return super().salario() * (1 + self.bonus_pct / 100)


class Vendedor(Empleado):
    COMISION = 0.05

    def __init__(self, nombre, salario_base):
        super().__init__(nombre, salario_base)
        self.ventas = []                                # una lista por vendedor

    def registrar_venta(self, importe):
        if not _es_numero(importe) or importe <= 0:
            raise ValueError(f"Importe inválido: {importe!r}")
        self.ventas.append(importe)

    def salario(self):
        return super().salario() + self.COMISION * sum(self.ventas)


class Practicante(Empleado):
    SALARIO_MAXIMO = 1000

    def __init__(self, nombre, salario_base):
        super().__init__(nombre, salario_base)
        if salario_base > self.SALARIO_MAXIMO:
            raise ValueError(f"Un practicante no puede cobrar más de ${self.SALARIO_MAXIMO}")


TIPOS = {
    "empleado": Empleado,
    "gerente": Gerente,
    "vendedor": Vendedor,
    "practicante": Practicante,
}


def crear_empleado(datos):
    argumentos = dict(datos)                 # copia: no tocamos el diccionario recibido
    tipo = argumentos.pop("tipo", None)
    if tipo not in TIPOS:
        raise ValueError(f"Tipo de empleado desconocido: {tipo!r}")
    return TIPOS[tipo](**argumentos)          # las clases son objetos: se guardan en un dict


def nomina(empleados):
    resultado = {}
    for empleado in empleados:
        resultado[empleado.nombre] = round(empleado.salario(), 2)
    return resultado

