exercises.solution:
class InventarioError(Exception):
    """Base de todos los errores del inventario."""


class ProductoNoEncontradoError(InventarioError):
    def __init__(self, sku):
        super().__init__(f"No existe el producto {sku!r}")
        self.sku = sku


class StockInsuficienteError(InventarioError):
    def __init__(self, sku, disponible, solicitado):
        super().__init__(f"Stock insuficiente de {sku}: hay {disponible}, se piden {solicitado}")
        self.sku = sku
        self.disponible = disponible
        self.solicitado = solicitado


def normalizar_sku(sku):
    if not isinstance(sku, str) or not sku.strip():
        raise ValueError("El SKU debe ser un texto no vacío")
    return sku.strip().upper()


class Producto:
    def __init__(self, sku, nombre, precio):
        if not isinstance(nombre, str) or not nombre.strip():
            raise ValueError("El nombre no puede estar vacío")
        self.sku = normalizar_sku(sku)
        self.nombre = nombre.strip()
        self.precio = precio                       # pasa por el setter

    @property
    def precio(self):
        return self._precio

    @precio.setter
    def precio(self, valor):
        if isinstance(valor, bool) or not isinstance(valor, (int, float)) or valor <= 0:
            raise ValueError(f"Precio inválido: {valor!r}")
        self._precio = valor

    def __repr__(self):
        return f"Producto({self.sku!r}, {self.nombre!r}, {self.precio!r})"


class Inventario:
    def __init__(self):
        self._productos = {}                       # sku -> Producto
        self._unidades = {}                        # sku -> unidades en stock

    @staticmethod
    def _validar_cantidad(cantidad, minimo):
        if isinstance(cantidad, bool) or not isinstance(cantidad, int) or cantidad < minimo:
            raise ValueError(f"Cantidad inválida: {cantidad!r}")

    def _clave(self, sku):
        """Normaliza el SKU y comprueba que existe."""
        clave = sku.strip().upper() if isinstance(sku, str) else sku
        if clave not in self._productos:
            raise ProductoNoEncontradoError(sku)
        return clave

    def alta(self, producto, cantidad=0):
        if not isinstance(producto, Producto):
            raise TypeError("Solo se pueden dar de alta objetos Producto")
        if producto.sku in self._productos:
            raise ValueError(f"El SKU {producto.sku} ya existe")
        self._validar_cantidad(cantidad, 0)
        self._productos[producto.sku] = producto   # guardamos el objeto, no una copia
        self._unidades[producto.sku] = cantidad

    def entrada(self, sku, cantidad):
        clave = self._clave(sku)
        self._validar_cantidad(cantidad, 1)
        self._unidades[clave] += cantidad
        return self._unidades[clave]

    def salida(self, sku, cantidad):
        clave = self._clave(sku)
        self._validar_cantidad(cantidad, 1)
        disponible = self._unidades[clave]
        if cantidad > disponible:
            raise StockInsuficienteError(clave, disponible, cantidad)
        self._unidades[clave] = disponible - cantidad
        return self._unidades[clave]

    def stock(self, sku):
        return self._unidades[self._clave(sku)]

    def producto(self, sku):
        return self._productos[self._clave(sku)]

    def valor_total(self):
        total = 0
        for sku, producto in self._productos.items():
            total += producto.precio * self._unidades[sku]
        return round(total, 2)

    def bajo_minimo(self, umbral):
        return sorted([sku for sku in self._unidades if self._unidades[sku] < umbral])

    def buscar(self, texto):
        patron = texto.casefold()
        encontrados = [p for p in self._productos.values() if patron in p.nombre.casefold()]
        return sorted(encontrados, key=lambda p: p.nombre.casefold())

