exercises.solution:
def _es_numero(valor):
    return isinstance(valor, (int, float)) and not isinstance(valor, bool)


def _validar_cantidad(cantidad):
    if isinstance(cantidad, bool) or not isinstance(cantidad, int) or cantidad < 1:
        raise ValueError(f"Cantidad inválida: {cantidad!r}")


class Producto:
    def __init__(self, nombre, precio):
        if not isinstance(nombre, str) or not nombre.strip():
            raise ValueError("El nombre del producto no puede estar vacío")
        if not _es_numero(precio) or precio <= 0:
            raise ValueError(f"Precio inválido: {precio!r}")
        self.nombre = nombre
        self.precio = precio

    def __repr__(self):
        return f"Producto({self.nombre!r}, {self.precio!r})"


class LineaCarrito:
    def __init__(self, producto, cantidad):
        _validar_cantidad(cantidad)
        self.producto = producto
        self.cantidad = cantidad

    @property
    def subtotal(self):
        return self.producto.precio * self.cantidad

    def __repr__(self):
        return f"LineaCarrito({self.producto!r}, {self.cantidad!r})"


class Descuento:
    """Base de los descuentos. El carrito solo exige calcular() y descripcion()."""

    def calcular(self, carrito):
        raise NotImplementedError

    def descripcion(self):
        raise NotImplementedError


class DescuentoPorcentaje(Descuento):
    def __init__(self, pct):
        if not _es_numero(pct) or not 0 < pct <= 100:
            raise ValueError(f"Porcentaje inválido: {pct!r}")
        self.pct = pct

    def calcular(self, carrito):
        return carrito.subtotal() * self.pct / 100

    def descripcion(self):
        return f"{self.pct}%"


class DescuentoFijo(Descuento):
    def __init__(self, importe, minimo=0):
        if not _es_numero(importe) or importe <= 0:
            raise ValueError(f"Importe inválido: {importe!r}")
        if not _es_numero(minimo) or minimo < 0:
            raise ValueError(f"Mínimo inválido: {minimo!r}")
        self.importe = importe
        self.minimo = minimo

    def calcular(self, carrito):
        subtotal = carrito.subtotal()
        if subtotal < self.minimo:
            return 0
        return min(self.importe, subtotal)

    def descripcion(self):
        return f"${self.importe:.2f}"


class TresPorDos(Descuento):
    def __init__(self, nombre):
        self.nombre = nombre

    def calcular(self, carrito):
        linea = carrito.linea(self.nombre)
        if linea is None:
            return 0
        return (linea.cantidad // 3) * linea.producto.precio

    def descripcion(self):
        return f"3x2 {self.nombre}"


class Carrito:
    def __init__(self):
        self._lineas = []          # composición: el carrito crea y posee sus líneas
        self._descuentos = []

    @property
    def lineas(self):
        return list(self._lineas)

    def linea(self, nombre):
        for linea in self._lineas:
            if linea.producto.nombre == nombre:
                return linea
        return None

    def agregar(self, producto, cantidad=1):
        _validar_cantidad(cantidad)
        existente = self.linea(producto.nombre)
        if existente is None:
            self._lineas.append(LineaCarrito(producto, cantidad))
        else:
            existente.cantidad += cantidad

    def quitar(self, nombre, cantidad=None):
        existente = self.linea(nombre)
        if existente is None:
            raise KeyError(nombre)
        if cantidad is None:
            self._lineas.remove(existente)
            return
        _validar_cantidad(cantidad)
        if cantidad > existente.cantidad:
            raise ValueError(f"Solo hay {existente.cantidad} unidades de {nombre}")
        existente.cantidad -= cantidad
        if existente.cantidad == 0:
            self._lineas.remove(existente)

    def num_articulos(self):
        total = 0
        for linea in self._lineas:
            total += linea.cantidad
        return total

    def subtotal(self):
        total = 0
        for linea in self._lineas:
            total += linea.subtotal
        return total

    def aplicar_descuento(self, descuento):
        # Duck typing: no exigimos heredar de Descuento, solo tener los dos métodos
        if not (callable(getattr(descuento, "calcular", None))
                and callable(getattr(descuento, "descripcion", None))):
            raise TypeError("Un descuento necesita los métodos calcular() y descripcion()")
        self._descuentos.append(descuento)

    def descuento_total(self):
        suma = 0
        for descuento in self._descuentos:
            suma += descuento.calcular(self)
        return min(suma, self.subtotal())

    def total(self):
        return round(self.subtotal() - self.descuento_total(), 2)

    def ticket(self):
        filas = []
        for linea in self._lineas:
            filas.append(f"{linea.producto.nombre} x{linea.cantidad}: {linea.subtotal:.2f}")
        filas.append(f"Subtotal: {self.subtotal():.2f}")
        for descuento in self._descuentos:
            importe = descuento.calcular(self)
            if importe > 0:
                filas.append(f"Descuento {descuento.descripcion()}: -{importe:.2f}")
        filas.append(f"Total: {self.total():.2f}")
        return "\n".join(filas)

