exercises.solution:
from datetime import date, timedelta


class BibliotecaError(Exception):
    """Base de todos los errores de la biblioteca."""


class NoEncontradoError(BibliotecaError):
    """No existe el libro, el socio o el préstamo."""


class NoDisponibleError(BibliotecaError):
    """El libro ya está prestado."""


class LimitePrestamosError(BibliotecaError):
    """El socio ha alcanzado su límite de préstamos."""


def _texto_valido(valor):
    return isinstance(valor, str) and valor.strip() != ""


def _limpiar_isbn(texto):
    return texto.replace("-", "").replace(" ", "")


class Libro:
    def __init__(self, isbn, titulo, autor):
        if not Libro.es_isbn_valido(isbn):
            raise ValueError(f"ISBN inválido: {isbn!r}")
        if not _texto_valido(titulo) or not _texto_valido(autor):
            raise ValueError("El título y el autor no pueden estar vacíos")
        self.isbn = _limpiar_isbn(isbn)
        self.titulo = titulo
        self.autor = autor

    @staticmethod
    def es_isbn_valido(texto):
        if not isinstance(texto, str):
            return False
        digitos = _limpiar_isbn(texto)
        if len(digitos) != 13:
            return False
        suma = 0
        for posicion, caracter in enumerate(digitos):
            if caracter not in "0123456789":
                return False
            peso = 1 if posicion % 2 == 0 else 3
            suma += int(caracter) * peso
        return suma % 10 == 0

    def __repr__(self):
        return f"Libro({self.isbn!r}, {self.titulo!r}, {self.autor!r})"


class Socio:
    LIMITE = 2
    DIAS_PRESTAMO = 14
    MULTA_DIA = 0.5

    def __init__(self, id_socio, nombre):
        if not _texto_valido(id_socio) or not _texto_valido(nombre):
            raise ValueError("El id y el nombre del socio no pueden estar vacíos")
        self.id_socio = id_socio
        self.nombre = nombre


class SocioPremium(Socio):
    LIMITE = 5
    DIAS_PRESTAMO = 30
    MULTA_DIA = 0.25


class Prestamo:
    def __init__(self, libro, socio, inicio):
        self.libro = libro
        self.socio = socio
        self.inicio = inicio

    @property
    def vence(self):
        return self.inicio + timedelta(days=self.socio.DIAS_PRESTAMO)

    def dias_retraso(self, hoy):
        return max(0, (hoy - self.vence).days)

    def multa(self, hoy):
        return round(self.dias_retraso(hoy) * self.socio.MULTA_DIA, 2)


class Biblioteca:
    def __init__(self):
        self._libros = {}        # isbn -> Libro
        self._socios = {}        # id_socio -> Socio
        self._prestamos = {}     # isbn -> Prestamo activo (orden de préstamo)

    def agregar_libro(self, libro):
        if not isinstance(libro, Libro):
            raise TypeError("Solo se pueden agregar objetos Libro")
        if libro.isbn in self._libros:
            raise ValueError(f"Ya existe un libro con ISBN {libro.isbn}")
        self._libros[libro.isbn] = libro

    def registrar_socio(self, socio):
        if not isinstance(socio, Socio):
            raise TypeError("Solo se pueden registrar objetos Socio")
        if socio.id_socio in self._socios:
            raise ValueError(f"Ya existe un socio con id {socio.id_socio}")
        self._socios[socio.id_socio] = socio

    def _libro(self, isbn):
        clave = _limpiar_isbn(isbn) if isinstance(isbn, str) else isbn
        if clave not in self._libros:
            raise NoEncontradoError(f"No existe el libro {isbn!r}")
        return self._libros[clave]

    def _socio(self, id_socio):
        if id_socio not in self._socios:
            raise NoEncontradoError(f"No existe el socio {id_socio!r}")
        return self._socios[id_socio]

    def prestar(self, isbn, id_socio, hoy):
        libro = self._libro(isbn)
        socio = self._socio(id_socio)
        if libro.isbn in self._prestamos:
            raise NoDisponibleError(f"«{libro.titulo}» ya está prestado")
        if len(self.prestamos_de(id_socio)) >= socio.LIMITE:
            raise LimitePrestamosError(f"{socio.nombre} ya tiene {socio.LIMITE} préstamos")
        prestamo = Prestamo(libro, socio, hoy)
        self._prestamos[libro.isbn] = prestamo
        return prestamo

    def devolver(self, isbn, hoy):
        libro = self._libro(isbn)
        prestamo = self._prestamos.pop(libro.isbn, None)
        if prestamo is None:
            raise NoEncontradoError(f"«{libro.titulo}» no está prestado")
        return prestamo.multa(hoy)

    def prestamos_de(self, id_socio):
        socio = self._socio(id_socio)
        return [p for p in self._prestamos.values() if p.socio is socio]

    def disponibles(self):
        libres = [libro for isbn, libro in self._libros.items() if isbn not in self._prestamos]
        return sorted(libres, key=lambda libro: libro.titulo)

    def vencidos(self, hoy):
        con_retraso = [p for p in self._prestamos.values() if p.dias_retraso(hoy) > 0]
        return sorted(con_retraso, key=lambda p: p.vence)

